import UIKit
final class AvatarCell: UITableViewCell {
    var representedID: Int?
    private var requestVersion = 0
    func newRequest(id: Int) -> (UIImage) -> Void {
        representedID = id
        requestVersion += 1
        let version = requestVersion
        imageView?.image = nil
        return { [weak self] image in
            guard let self, self.representedID == id,
                  self.requestVersion == version else { return }
            self.imageView?.image = image
        }
    }
    override func prepareForReuse() {
        super.prepareForReuse()
        representedID = nil
        requestVersion += 1
    }
}
let cell = AvatarCell(style: .default, reuseIdentifier: "Avatar")
let first = cell.newRequest(id: 101)
let second = cell.newRequest(id: 101)
let oldImage = UIImage()
let currentImage = UIImage()
second(currentImage)
first(oldImage)
assert(cell.imageView?.image === currentImage)

Текущая обложка сохраняется, потому что первый callback имеет прежнюю версию. prepareForReuse тоже делает ранее созданные callbacks недействительными.
